  var fl = g.at([[200, 200, 80], [380, 170, 78], [300, 330, 80], [150, 380, 64], [440, 350, 66]], [[210, 220, 90], [390, 200, 90], [300, 350, 90]], [[220, 250, 120], [390, 290, 110]]);
