    g.S(h.path([x - 70, y]).L([x + 70, y]).L([x + 120, y + 60]).L([x + 96, y + 100]).L([x + 70, y + 80]).L([x + 70, y + 260]).L([x - 70, y + 260]).L([x - 70, y + 80]).L([x - 96, y + 100]).L([x - 120, y + 60]).Z());
