    var n = g.at(11, 0, 0);                                        // the chain's links from Tier 1 only
    for (var i = 1; i <= n; i++){ var p = at(i / (n + 1)), p2 = at(i / (n + 1) + .01), a = Math.atan2(p2[1] - p[1], p2[0] - p[0]) * 180 / Math.PI; g.S(h.ellipse(p[0], p[1], 20, 11, a + (i % 2 ? 0 : 90))); }
