  if (g.lvl >= 2) g.at([[250, 330], [370, 300]], [[260, 580], [360, 560]]).forEach(function(c){ g.L(h.line([c[0], 800], [c[0], c[1] + 80])); g.S(h.rrect(c[0] - 18, c[1], 36, 90, 18)); });
