function sizeOf(b){ var bw = b.x1 - b.x0, bh = b.y1 - b.y0; return { cx:(b.x0 + b.x1) / 2, y:b.y1, w:Math.max(bw * 1.32, bh * .9), u:Math.max(bw, bh) / 420 }; }
