  for (var i = 0; i < n; i++){ var a = i / n * Math.PI * 2, k = lobes ? 1 - (i % 2 ? depth : 0) : 1; pts.push([cx + Math.cos(a) * rx * k, cy + Math.sin(a) * ry * k]); }
